import { useContext, useState, useEffect } from 'react';
import { AuthContext } from '../../context/authContext';
import { Link } from "react-router-dom";
import axios from 'axios';
import './posts.scss';

// Import icons
import FavoriteBorderOutlinedIcon from "@mui/icons-material/FavoriteBorderOutlined";
import FavoriteOutlinedIcon from "@mui/icons-material/FavoriteOutlined";
import TextsmsOutlinedIcon from "@mui/icons-material/TextsmsOutlined";
import ShareOutlinedIcon from "@mui/icons-material/ShareOutlined";
import MoreHorizIcon from "@mui/icons-material/MoreHoriz";

const Posts = () => {
  const { currentUser, accessToken } = useContext(AuthContext);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [commentInputs, setCommentInputs] = useState({});
  const [openComments, setOpenComments] = useState({});

  const getMediaUrl = (media) => {
    if (!media) {
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (media.startsWith('http')) {
      return media;
    }
    const normalizedPath = media.replace(/^\/Uploads\//i, '/Uploads/');
    return `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
  };

  const getMediaType = (mediaUrl) => {
    if (!mediaUrl) return null;
    if (mediaUrl.match(/\.(mp4|mov)$/i)) return 'video';
    if (mediaUrl.match(/\.(mp3|wav)$/i)) return 'audio';
    return 'image'; // Default to image for other extensions
  };

  const fetchPosts = async () => {
    setLoading(true);
    setError(null);
    try {
      if (!accessToken) {
        throw new Error('No authentication token found. Please log in.');
      }
      console.log('Posts: Fetching posts');
      const res = await axios.get('http://localhost:5000/api/posts', {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      const mappedPosts = res.data.map((post) => {
        // Ensure userId is properly formatted
        let userId = post.userId;
        if (userId && typeof userId === 'object') {
          userId = {
            _id: String(userId._id), // Ensure _id is a string
            username: userId.username || 'Unknown',
            name: userId.name || 'Unknown',
            profilePicture: userId.profilePicture || '',
          };
        } else if (userId) {
          userId = {
            _id: String(userId),
            username: 'Unknown',
            name: post.name || 'Unknown',
            profilePicture: post.profilePicture || '',
          };
        }

        return {
          ...post,
          media: post.image, // Map image to media
          desc: post.description || post.desc, // Handle both description and desc
        };
      });

      console.log('Posts: Fetched posts:', mappedPosts.length);
      setPosts(mappedPosts || []);
    } catch (err) {
      console.error('Posts: Error fetching posts:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
      });
      setError(err.response?.data?.message || 'Failed to load posts');
    } finally {
      setLoading(false);
    }
  };

  const fetchPostDetails = async (postId) => {
    try {
      if (!accessToken) {
        throw new Error('No authentication token found.');
      }
      console.log(`Posts: Fetching details for post ${postId}`);
      const res = await axios.get(`http://localhost:5000/api/posts/${postId}`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      console.log(`Posts: Fetched post details for ${postId}:`, res.data);
      setPosts((prev) =>
        prev.map((post) =>
          post._id === postId
            ? {
                ...post,
                likes: res.data.likes,
                likesCount: res.data.likesCount,
                comments: res.data.comments,
                commentsCount: res.data.commentsCount,
                likedBy: res.data.likes.map(user => String(user._id)),
              }
            : post
        )
      );
    } catch (err) {
      console.error('Posts: Error fetching post details:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
      });
      setError(err.response?.data?.message || 'Failed to load post details');
    }
  };

  const handleLike = async (postId) => {
    try {
      if (!accessToken || !currentUser || !currentUser._id) {
        throw new Error('No authentication token or user ID found.');
      }

      const userId = String(currentUser._id);
      console.log(`Posts: Liking post ${postId} with userId: ${userId}`);

      const res = await axios.post(
        `http://localhost:5000/api/posts/${postId}/like`,
        { userId },
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      console.log(`Posts: Like response for post ${postId}:`, res.data);
      setPosts((prev) =>
        prev.map((post) =>
          post._id === postId
            ? {
                ...post,
                likes: res.data.likes,
                likesCount: res.data.likesCount,
                likedBy: res.data.likedBy,
              }
            : post
        )
      );
    } catch (err) {
      console.error('Posts: Error toggling like:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
      });
      setError(err.response?.data?.message || 'Failed to like post');
    }
  };

  const handleCommentSubmit = async (postId, e) => {
    e.preventDefault();
    const content = commentInputs[postId]?.trim();
    if (!content) return;

    try {
      if (!accessToken || !currentUser || !currentUser._id) {
        throw new Error('No authentication token or user ID found.');
      }

      const userId = String(currentUser._id);
      console.log(`Posts: Submitting comment for post ${postId} with userId: ${userId}, content: ${content}`);

      const res = await axios.post(
        `http://localhost:5000/api/posts/${postId}/comment`,
        { userId, content },
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      console.log(`Posts: Comment response for post ${postId}:`, res.data);
      setPosts((prev) =>
        prev.map((post) =>
          post._id === postId
            ? {
                ...post,
                comments: res.data.comments,
                commentsCount: res.data.commentsCount,
              }
            : post
        )
      );
      setCommentInputs((prev) => ({ ...prev, [postId]: '' }));
    } catch (err) {
      console.error('Posts: Error submitting comment:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
      });
      setError(err.response?.data?.message || 'Failed to add comment');
    }
  };

  const toggleComments = (postId) => {
    setOpenComments(prev => ({
      ...prev,
      [postId]: !prev[postId]
    }));
    if (!openComments[postId]) {
      fetchPostDetails(postId); // Fetch fresh likes and comments when opening
    }
  };

  useEffect(() => {
    if (accessToken && currentUser) {
      console.log('Current user in Posts:', {
        id: currentUser._id,
        idType: typeof currentUser._id,
        username: currentUser.username,
        accessToken: accessToken ? 'Present' : 'Missing',
      });
      fetchPosts();
    } else {
      console.warn('Posts: Missing auth data:', {
        accessToken: !!accessToken,
        currentUser: !!currentUser,
      });
      setError('Please log in to view posts');
    }

    const handleNewPost = () => {
      console.log('Posts: New post event received');
      fetchPosts();
    };
    window.addEventListener('newPost', handleNewPost);
    return () => window.removeEventListener('newPost', handleNewPost);
  }, [accessToken, currentUser]);

  if (loading) return <div className="posts">Loading posts...</div>;
  if (error) return <div className="posts error">{error}</div>;

  return (
    <div className="posts">
      {posts.length > 0 ? (
        posts.map((post) => (
          <div key={post._id} className="post">
            <div className="container">
              <div className="user">
                <div className="userInfo">
                  <img
                    src={getMediaUrl(post.userId?.profilePicture)}
                    alt={`${post.userId.name}'s profile`}
                    className="post-avatar"
                    onError={(e) => {
                      e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                    }}
                  />
                  <div className="details">
                    <Link
                      to={`/profile/${post.userId._id}`}
                      style={{ textDecoration: "none", color: "inherit" }}
                    >
                      <span className="name">{post.userId.name}</span>
                    </Link>
                    <span className="date">{new Date(post.createdAt).toLocaleString()}</span>
                  </div>
                </div>
                <MoreHorizIcon />
              </div>
              <div className="content">
                {post.desc && <p>{post.desc}</p>}
                {post.location && <p className="location">📍 {post.location}</p>}
                {post.taggedFriends?.length > 0 && (
                  <p className="tagged">
                    Tagged: {post.taggedFriends.map((f) => f.name).join(', ')}
                  </p>
                )}
                {post.media && (
                  <div className="post-media">
                    {getMediaType(post.media) === 'video' ? (
                      <video
                        src={getMediaUrl(post.media)}
                        controls
                        className="media"
                        onError={(e) => {
                          console.error(`Posts: Video load error for post ${post._id}:`, e);
                          e.target.style.display = 'none';
                        }}
                      />
                    ) : getMediaType(post.media) === 'audio' ? (
                      <audio
                        src={getMediaUrl(post.media)}
                        controls
                        className="media"
                        onError={(e) => {
                          console.error(`Posts: Audio load error for post ${post._id}:`, e);
                          e.target.style.display = 'none';
                        }}
                      />
                    ) : (
                      <img
                        src={getMediaUrl(post.media)}
                        alt="Post media"
                        className="media"
                        onError={(e) => {
                          console.error(`Posts: Image load error for post ${post._id}:`, e);
                          e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                        }}
                      />
                    )}
                  </div>
                )}
              </div>
              <div className="info">
                <div className="item" onClick={() => handleLike(post._id)}>
                  {post.likedBy?.includes(currentUser._id) ? (
                    <FavoriteOutlinedIcon className="liked" />
                  ) : (
                    <FavoriteBorderOutlinedIcon />
                  )}
                  {post.likesCount || 0} {post.likesCount === 1 ? 'Like' : 'Likes'}
                </div>
                <div className="item" onClick={() => toggleComments(post._id)}>
                  <TextsmsOutlinedIcon />
                  {post.commentsCount || 0} {post.commentsCount === 1 ? 'Comment' : 'Comments'}
                </div>
                <div className="item">
                  <ShareOutlinedIcon />
                  Share
                </div>
              </div>

              {openComments[post._id] && (
                <div className="comments">
                  <form onSubmit={(e) => handleCommentSubmit(post._id, e)}>
                    <input
                      type="text"
                      placeholder="Add a comment..."
                      value={commentInputs[post._id] || ''}
                      onChange={(e) =>
                        setCommentInputs((prev) => ({
                          ...prev,
                          [post._id]: e.target.value,
                        }))
                      }
                    />
                    <button type="submit" disabled={!commentInputs[post._id]?.trim()}>
                      Post
                    </button>
                  </form>

                  {post.comments?.length > 0 && (
                    <div className="comments-list">
                      {post.comments.map((comment) => (
                        <div key={comment._id} className="comment">
                          <span className="comment-user">{comment.userId?.name || 'Unknown'}</span>
                          <span className="comment-content">{comment.content}</span>
                          <span className="comment-timestamp">
                            {new Date(comment.createdAt).toLocaleString()}
                          </span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ))
      ) : (
        <div className="no-posts">No posts to display.</div>
      )}
    </div>
  );
};

export default Posts;
